ALTER TABLE public.circles ADD COLUMN is_test boolean NOT NULL DEFAULT false, ADD COLUMN required_email_domain text;
UPDATE public.circles SET required_email_domain='berkeley.edu' WHERE name='Haas FTMBA 2027';
ALTER TABLE public.profiles ADD COLUMN match_notifications boolean NOT NULL DEFAULT true;
ALTER TABLE public.events ADD COLUMN is_test boolean NOT NULL DEFAULT false;
UPDATE public.events e SET is_test=c.is_test FROM public.circles c WHERE c.id=e.circle_id;
CREATE TABLE public.match_revision (id boolean PRIMARY KEY DEFAULT true CHECK(id), revision bigint NOT NULL DEFAULT 0, applied bigint NOT NULL DEFAULT -1);
GRANT ALL ON public.match_revision TO service_role;
ALTER TABLE public.match_revision ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.recalculate_matches() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.match_revision(id,revision) VALUES(true,1) ON CONFLICT(id) DO UPDATE SET revision=match_revision.revision+1; RETURN NULL; END $$;
CREATE TRIGGER memberships_match AFTER INSERT OR DELETE ON public.circle_members FOR EACH STATEMENT EXECUTE FUNCTION public.recalculate_matches();
CREATE FUNCTION public.apply_matches(expected bigint, pairs jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v bigint; BEGIN SELECT revision INTO v FROM public.match_revision WHERE id=true FOR UPDATE; IF v IS DISTINCT FROM expected THEN RETURN false; END IF;
DELETE FROM public.item_matches m WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(pairs) AS p(item_id uuid,wish_id uuid,user_id uuid) WHERE p.item_id=m.item_id AND p.wish_id=m.wish_id);
WITH fresh AS (INSERT INTO public.item_matches(item_id,wish_id,user_id) SELECT p.item_id,p.wish_id,p.user_id FROM jsonb_to_recordset(pairs) AS p(item_id uuid,wish_id uuid,user_id uuid) JOIN public.items i ON i.id=p.item_id JOIN public.wishes w ON w.id=p.wish_id AND w.user_id=p.user_id AND w.circle_id=i.circle_id JOIN public.circle_members cm ON cm.circle_id=i.circle_id AND cm.user_id=w.user_id WHERE i.status='available' AND i.expires_at>now() AND i.giver_id<>w.user_id ON CONFLICT DO NOTHING RETURNING *) INSERT INTO public.events(user_id,item_id,circle_id,name) SELECT f.user_id,f.item_id,i.circle_id,'match_created' FROM fresh f JOIN public.items i ON i.id=f.item_id;
UPDATE public.match_revision SET applied=expected WHERE id=true; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.apply_matches(bigint,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.apply_matches(bigint,jsonb) TO service_role;
COMMENT ON FUNCTION public.wish_matches(text,text,text) IS 'DEPRECATED: live matches use the single shared pure TypeScript rule and apply_matches';
CREATE FUNCTION public.clean_text(t text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT trim(regexp_replace(regexp_replace(coalesce(t,''),'<(script|style)[^>]*>.*?</(script|style)\s*>','','gi'),'<[^>]*>','','g')) $$;
CREATE FUNCTION public.guard_text() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF TG_TABLE_NAME='items' THEN NEW.title=public.clean_text(NEW.title); NEW.description=public.clean_text(NEW.description); IF length(NEW.title) NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION 'Titles must be 1–80 characters'; END IF;
ELSIF TG_TABLE_NAME='wishes' THEN NEW.text=public.clean_text(NEW.text); IF length(NEW.text) NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'Wishes must be 1–60 characters'; END IF;
ELSIF TG_TABLE_NAME='messages' THEN NEW.text=public.clean_text(NEW.text);
ELSIF TG_TABLE_NAME='profiles' THEN NEW.display_name=public.clean_text(NEW.display_name);
ELSIF TG_TABLE_NAME='circles' THEN NEW.name=public.clean_text(NEW.name);
ELSIF TG_TABLE_NAME='chat_reports' THEN NEW.reason=public.clean_text(NEW.reason);
ELSIF TG_TABLE_NAME='synonyms' THEN NEW.category=public.clean_text(NEW.category); NEW.words=ARRAY(SELECT public.clean_text(x) FROM unnest(NEW.words) x);
END IF; RETURN NEW; END $$;
CREATE TRIGGER safe_items BEFORE INSERT OR UPDATE ON public.items FOR EACH ROW EXECUTE FUNCTION public.guard_text();
CREATE TRIGGER safe_wishes BEFORE INSERT OR UPDATE ON public.wishes FOR EACH ROW EXECUTE FUNCTION public.guard_text();
CREATE TRIGGER safe_messages BEFORE INSERT OR UPDATE ON public.messages FOR EACH ROW EXECUTE FUNCTION public.guard_text();
CREATE TRIGGER safe_profiles BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_text();
CREATE TRIGGER safe_circles BEFORE INSERT OR UPDATE ON public.circles FOR EACH ROW EXECUTE FUNCTION public.guard_text();
CREATE TRIGGER safe_reports BEFORE INSERT OR UPDATE ON public.chat_reports FOR EACH ROW EXECUTE FUNCTION public.guard_text();
CREATE TRIGGER safe_synonyms BEFORE INSERT OR UPDATE ON public.synonyms FOR EACH ROW EXECUTE FUNCTION public.guard_text();
CREATE FUNCTION public.member_eligibility() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE domain text; test boolean; email text; BEGIN SELECT required_email_domain,is_test INTO domain,test FROM public.circles WHERE id=NEW.circle_id; IF test AND NOT public.is_admin() THEN RAISE EXCEPTION 'Only an admin can add test-circle members'; END IF; IF domain IS NOT NULL THEN SELECT u.email INTO email FROM auth.users u WHERE u.id=NEW.user_id AND u.email_confirmed_at IS NOT NULL; IF email IS NULL OR lower(split_part(email,'@',2))<>lower(domain) THEN RAISE EXCEPTION 'Sign in with a verified @berkeley.edu email to join this circle'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER circle_eligibility BEFORE INSERT ON public.circle_members FOR EACH ROW EXECUTE FUNCTION public.member_eligibility();
CREATE FUNCTION public.tag_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.is_test=coalesce((SELECT is_test FROM public.circles WHERE id=NEW.circle_id),false); RETURN NEW; END $$;
CREATE TRIGGER event_test_tag BEFORE INSERT ON public.events FOR EACH ROW EXECUTE FUNCTION public.tag_event();
CREATE FUNCTION public.match_notification_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.kind='match' AND (NOT coalesce((SELECT match_notifications FROM public.profiles WHERE id=NEW.user_id),true) OR extract(hour FROM now() AT TIME ZONE 'America/Los_Angeles')<8 OR extract(hour FROM now() AT TIME ZONE 'America/Los_Angeles')>=21) THEN RETURN NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER match_notification_preference BEFORE INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.match_notification_guard();
CREATE FUNCTION public.claim_expiry_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='expired' AND OLD.status<>'expired' THEN INSERT INTO public.notifications(user_id,item_id,kind) SELECT NEW.receiver_id,NEW.item_id,'free_again' UNION ALL SELECT i.giver_id,NEW.item_id,'free_again' FROM public.items i WHERE i.id=NEW.item_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER expired_claim_notice AFTER UPDATE OF status ON public.claims FOR EACH ROW EXECUTE FUNCTION public.claim_expiry_notice();
CREATE FUNCTION public.admin_circle_action(action text,payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid=(payload->>'circle_id')::uuid; rid uuid; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin access required'; END IF;
IF action='create_test_circle' THEN INSERT INTO public.circles(name,is_test) VALUES('Test circle',true) RETURNING id INTO rid; INSERT INTO public.circle_members(circle_id,user_id) VALUES(rid,auth.uid()); RETURN jsonb_build_object('id',rid);
ELSIF action='rotate_invite' THEN UPDATE public.circles SET invite_token=gen_random_uuid() WHERE id=cid;
ELSIF action='remove_member' THEN IF (payload->>'user_id')::uuid=auth.uid() THEN RAISE EXCEPTION 'You cannot remove yourself here'; END IF; IF EXISTS(SELECT 1 FROM public.claims c JOIN public.items i ON i.id=c.item_id WHERE i.circle_id=cid AND c.status IN('claimed','pickup_arranged') AND (i.giver_id=(payload->>'user_id')::uuid OR c.receiver_id=(payload->>'user_id')::uuid)) THEN RAISE EXCEPTION 'Finish or expire this member’s active pickups before removing them'; END IF; DELETE FROM public.circle_members WHERE circle_id=cid AND user_id=(payload->>'user_id')::uuid;
ELSIF action='add_test_member' THEN IF NOT EXISTS(SELECT 1 FROM public.circles WHERE id=cid AND is_test) THEN RAISE EXCEPTION 'Only test circles support adding test accounts'; END IF; INSERT INTO public.circle_members(circle_id,user_id) VALUES(cid,(payload->>'user_id')::uuid) ON CONFLICT DO NOTHING;
ELSE RAISE EXCEPTION 'Unknown circle action'; END IF; RETURN '{}'; END $$;
CREATE FUNCTION public.admin_members() RETURNS TABLE(circle_id uuid,user_id uuid,display_name text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin access required'; END IF; RETURN QUERY SELECT cm.circle_id,cm.user_id,p.display_name FROM public.circle_members cm JOIN public.profiles p ON p.id=cm.user_id; END $$;
REVOKE ALL ON FUNCTION public.admin_circle_action(text,jsonb),public.admin_members() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_circle_action(text,jsonb),public.admin_members() TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_metrics() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin access required'; END IF;
WITH real_events AS (SELECT * FROM public.events WHERE NOT is_test), real_items AS (SELECT i.* FROM public.items i JOIN public.circles c ON c.id=i.circle_id WHERE NOT c.is_test), weekly AS (SELECT date_trunc('week',created_at)::date week,count(DISTINCT user_id) members FROM real_events GROUP BY 1)
SELECT jsonb_build_object('counts',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT date_trunc('week',created_at)::date week,name,count(*) count FROM real_events GROUP BY 1,2 ORDER BY 1 DESC,2) x),'outcomes',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT date_trunc('week',i.created_at)::date week,count(*) posted,round(100.0*count(*) FILTER(WHERE first_claim<=i.created_at+interval '3 days')/nullif(count(*),0),1) claimed_within_3_days,percentile_cont(0.5) WITHIN GROUP(ORDER BY extract(epoch FROM first_claim-i.created_at)/3600) median_hours_to_claim FROM real_items i LEFT JOIN (SELECT item_id,min(created_at) first_claim FROM public.claims GROUP BY item_id) c ON c.item_id=i.id GROUP BY 1 ORDER BY 1 DESC) x),'active',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT w.week,w.members,round(w.members::numeric/nullif(p.members,0),2) activity_ratio FROM weekly w LEFT JOIN weekly p ON p.week=w.week-7 ORDER BY w.week DESC) x),'rates',jsonb_build_object('no_show',(SELECT round(100.0*count(*) FILTER(WHERE cl.status='expired')/nullif(count(*),0),1) FROM public.claims cl JOIN real_items i ON i.id=cl.item_id),'second_post',(SELECT round(100.0*count(*) FILTER(WHERE n>=2)/nullif(count(*),0),1) FROM (SELECT giver_id,count(*) n FROM real_items GROUP BY giver_id) g),'clearout_interest',(SELECT round(100.0*count(*) FILTER(WHERE name='clearout_interest_yes')/nullif(count(*),0),1) FROM real_events WHERE name IN('clearout_interest_yes','clearout_interest_no'))),'reports',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT r.id,r.claim_id,r.reason,r.created_at FROM public.chat_reports r JOIN public.claims cl ON cl.id=r.claim_id JOIN real_items i ON i.id=cl.item_id ORDER BY r.created_at DESC LIMIT 100) x)) INTO result; RETURN result; END $$;